$src=$work.'/origin';$dst=$work.'/destination';foreach([$src,$dst] as $dir){mkdir($dir);mkdir($dir.'/wp-content');mkdir($dir.'/wp-content/plugins');mkdir($dir.'/wp-content/plugins/f2-backup-local');}
