$values=['home'=>$from,'siteurl'=>$from,'src_user_roles'=>serialize(['administrator'=>['name'=>'Administrator','capabilities'=>['manage_options'=>true]]]),'builder'=>serialize(['url'=>$from.'/media.jpg','path'=>$src.'/wp-content/uploads','json'=>json_encode(['url'=>$from.'/page'])]),'rewrite_rules'=>serialize(['old'=>'rule']),'_transient_something'=>'oldcache'];
