$d->query('CREATE TABLE src_posts(ID int PRIMARY KEY,post_content longtext,guid varchar(255))');$q=$d->prepare('INSERT INTO src_posts VALUES(1,?,?)');$link=$from.'/post';$q->bind_param('ss',$link,$link);$q->execute();
