$b=$work.'/migration-backup';mkdir($b);$st=['type'=>'backup','phase'=>'db','root'=>$src,'created'=>gmdate('c'),'home'=>$from,'siteurl'=>$from,'prefix'=>'src_','wp_version'=>'fixture','files'=>0,'bytes'=>0,'rows'=>0,'exclude'=>[],'tables'=>F2SB_Engine::tables($d,'src_'),'table_i'=>0,'row_i'=>0,'schema_written'=>false];F2SB_Engine::save($b.'/state.json',$st);F2SB_Engine::save($b.'/config.json',$sourceCfg);advance($b,'done');
$t=F2SB_Engine::db($targetCfg);$t->query('CREATE TABLE dest_options(option_id int PRIMARY KEY,option_name varchar(191),option_value longtext)');$t->query("INSERT INTO dest_options VALUES(1,'home','newinstall')");$t->query('CREATE TABLE unrelated(id int)');$t->query('INSERT INTO unrelated VALUES(42)');
function migrationJob($name,$work,$backup,$dst,$cfg,$url,$sourceRoot=''){$job=$work.'/'.$name;mkdir($job);copy($backup.'/backup.zip',$job.'/backup.zip');F2SB_Engine::save($job.'/config.json',$cfg);F2SB_Engine::save($job.'/state.json',['type'=>'restore','phase'=>'inspect','root'=>$dst,'home'=>$url,'siteurl'=>$url,'prefix'=>'dest_','created'=>gmdate('c'),'exclude'=>[],'prune'=>true,'source_root'=>$sourceRoot]);advance($job,'ready');return $job;}
